import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.BXzK3EA4.js";const _=JSON.parse('{"title":"设计模式","description":"GoF 常用设计模式的原理与真实应用场景。","frontmatter":{},"headers":[],"relativePath":"计算机基础/design-patterns/index.md","filePath":"计算机基础/design-patterns/index.md","lastUpdated":1793545253000}'),i={name:"计算机基础/design-patterns/index.md"};function l(s,e,o,d,p,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="设计模式" tabindex="-1">设计模式 <a class="header-anchor" href="#设计模式" aria-label="Permalink to &quot;设计模式&quot;">​</a></h1><blockquote><p>GoF 常用设计模式的原理与真实应用场景。</p></blockquote><p>每个模式都给出问题场景、类结构与可运行代码。</p><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="/计算机基础/design-patterns/1-Factory-Pattern">工厂模式</a></li><li><a href="/计算机基础/design-patterns/2-Observer-Pattern">发布订阅、观察者模式</a></li><li><a href="/计算机基础/design-patterns/3-Proxy-Pattern">代理模式</a></li><li><a href="/计算机基础/design-patterns/4-Singleton-Pattern">单例模式</a></li><li><a href="/计算机基础/design-patterns/5-Strategy-Pattern">策略模式</a></li><li><a href="/计算机基础/design-patterns/6-design">设计模式总览</a></li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>GoF 模式按「<strong>创建型 / 结构型 / 行为型</strong>」分类,每个模式记住「问题 → 结构 → 代价」。</li><li>必会:工厂(多实现解耦)、观察者/发布订阅(事件驱动)、代理(控制访问与缓存)、单例(全局唯一)、策略(算法可替换)。</li><li>面试常问「发布订阅 vs 观察者」:发布订阅多了一个<strong>事件通道</strong>,双方互不感知;观察者是观察者直接持有被观察者引用。</li><li>前端映射:观察者 → EventEmitter / RxJS;策略 → 权限与支付渠道切换;单例 → 全局配置;工厂 → 组件按类型创建。</li><li>加分:指出模式的<strong>代价</strong>(单例难以测试、策略类爆炸),体现不是纸上谈兵。</li></ul>',7)])])}const g=t(i,[["render",l]]);export{_ as __pageData,g as default};
